import{_ as r,h as l,i,c as s,v as e,p as n,x as t,m as p,e as h,S as d}from"./chunks/framework.Dvtg8yj2.js";const L=JSON.parse('{"title":"ALiBi","description":"","frontmatter":{"title":"ALiBi","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/alibi.md","filePath":"llm/alibi.md","lastUpdated":1788454257000}'),E={name:"llm/alibi.md"};function m(B,a,A,c,_,u){const o=l("Mermaid");return i(),s("div",null,[a[1]||(a[1]=e('<h1 id="alibi" tabindex="-1">ALiBi <a class="header-anchor" href="#alibi" aria-label="Permalink to &quot;ALiBi&quot;">​</a></h1><div class="epigraph"><p>先在短序列上训练，再在长序列上测试：给注意力加上与距离成正比的线性偏置，输入长度就能外推。</p><footer>—— Press、Smith、Lewis，Train Short, Test Long，2021</footer></div><p>绝对位置嵌入把每个下标写成一张查找表，正弦编码把下标写成固定频率的三角函数，RoPE 把下标写进查询与键的旋转角。它们都假设模型在训练长度之内见过「位置」本身。Press、Smith 与 Lewis 在 2021 年的 ALiBi 论文里走了另一条路：位置不进入表示，只进入注意力的 logits，而且是一条按距离下降的直线。训练可以停在两千词附近，推理却常常还能走到更长的上下文。它和后面的 YaRN、位置插值不是同一类补丁——ALiBi 从一开始就按外推来设计偏置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Transformer 的自注意力对位置置换是等变的，若不额外注入顺序，因果掩码之外的内容几乎分不清「谁在谁前面」。早期做法是给每个位置加一个向量。这条路在训练长度 \\(L_{\\text{train}}\\) 之内很稳，一出界就出问题：可学习嵌入没有对应行，正弦与 RoPE 的相位也落到训练分布之外。于是出现一种常见工程循环——先按短窗口预训练，再为长窗口重新训练或插值。</p><p>外推失败并不只是「没见过下标 \\(L_{\\text{train}}+1\\)」。更尖锐的是：远处 token 的注意力权重，在训练里从未被要求承担「隔得很远仍可能相关」的负担；模型会把高频的局部模式学死，把长程依赖交给碰巧出现的绝对下标。一旦下标变大，局部统计还在，长程结构却对不齐。</p><p>ALiBi 要回答的问题因此很具体：能不能让位置信息只作为「离得越远越不该看」的归纳偏置，从而训练短、推理长，而不必准备一套会过期的位置表。<span class="marginnote">外推的真正难点往往不是缺一个下标，而是训练时从未给过「更远」的注意力分配。线性负偏置把「更远」写成一条在训练里就已经成立的直线，推理时只是把直线延长。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ALiBi 不向词嵌入加位置向量。第 \\(i\\) 个查询与第 \\(j\\) 个键的注意力 logits 写成</p> \\[\\text{score}(q_i, k_j) = \\frac{q_i^\\top k_j}{\\sqrt{d}} - m |i-j| \\]<p>其中 \\(m&gt;0\\) 是该头固定的斜率。因果语言模型里 \\(j\\le i\\)，距离就是 \\(i-j\\)，偏置为 \\(-m(i-j)\\)。距离为零时偏置为零，距离增大时 logits 线性变负，softmax 之后远处质量被压低。</p><p>每个头的斜率不同，且在训练前就定死，不随数据学习。Press 等人采用几何序列：八个头时斜率取 \\(1/2,1/4,\\ldots,1/256\\)；头数不是八则在这条几何序列上插值。有的头衰减很快，几乎只看近邻；有的头衰减很慢，仍能把远处信号留在可计算的动态范围里。</p>',12)),(i(),n(d,null,{default:t(()=>[h(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E5%90%91%E9%87%8F%22%5D%20--%3E%20S%5B%22%E7%82%B9%E7%A7%AF%E5%BE%97%E5%88%86%22%5D%0A%20%20K%5B%22%E9%94%AE%E5%90%91%E9%87%8F%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20B%5B%22%E5%87%8F%E5%8E%BB%E6%96%9C%E7%8E%87%E4%B9%98%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20D%5B%22%E4%BD%8D%E7%BD%AE%E5%B7%AE%E7%BB%9D%E5%AF%B9%E5%80%BC%22%5D%20--%3E%20B%0A%20%20B%20--%3E%20M%5B%22Softmax%20%E4%B8%8E%E5%8A%A0%E6%9D%83%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>实现上只需在注意力分数矩阵上加一个与下标差有关的下三角偏置，不必改投影矩阵，也不必存位置嵌入。训练长度可以明显短于目标推理长度——这正是论文副标题 Train Short, Test Long 的操作含义。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="线性偏置如何改写注意力分配" tabindex="-1">线性偏置如何改写注意力分配 <a class="header-anchor" href="#线性偏置如何改写注意力分配" aria-label="Permalink to &quot;线性偏置如何改写注意力分配&quot;">​</a></h3><p>把偏置看成在 logit 空间里的势：相邻位置势为零，每远一步就掉 \\(m\\)。softmax 对平移不变，对线性倾斜却敏感——同一内容相似度下，近处永远比远处更容易被选中。这与「先算内容、再乘一个与距离有关的门」不同：门若在概率空间相乘，远处只要内容极高仍可能压过近处；加在 logit 上则是指数级惩罚，\\(e^{-m\\Delta}\\) 会把差距拉成乘法因子。</p><p>因此 ALiBi 不是在表示里编码「第 17 个位置」，而是编码「相对你有多远」。相对距离在训练窗口里密集出现，推理窗口只是把同一相对量取到更大的值。只要内容点积的尺度没有随着长度崩掉，偏置的几何意义仍然成立。</p><h3 id="斜率的几何序列" tabindex="-1">斜率的几何序列 <a class="header-anchor" href="#斜率的几何序列" aria-label="Permalink to &quot;斜率的几何序列&quot;">​</a></h3><p>若所有头共用一个 \\(m\\)，网络只能选择一种衰减速度：太大则长程全灭，太小则近邻优势不够。几何序列把衰减谱摊开。衰减快的头承担局部句法与相邻指代，衰减慢的头承担段落级一致与稀远共现。训练时这些头在同一批短序列上同时更新，但它们对距离的敏感度从一开始就错开，避免所有头挤在同一有效窗口里。</p><p><span class="marginnote">斜率不学习，是为了堵住一条捷径：若 \\(m\\) 可训，模型可能把所有头的衰减都收到训练长度之内，外推时又变回「没见过更远」。固定几何序列等于把有效感受野写成超参数，而不是写成可被短上下文拟合掉的参数。</span></p><h3 id="与绝对位置和-rope-的对比" tabindex="-1">与绝对位置和 RoPE 的对比 <a class="header-anchor" href="#与绝对位置和-rope-的对比" aria-label="Permalink to &quot;与绝对位置和 RoPE 的对比&quot;">​</a></h3><p>绝对嵌入把 \\(i\\) 变成加性向量，模型必须把「下标」当作特征来用；超出表长就没有合法特征。RoPE 把 \\(i\\) 写进旋转角，相对位置进入点积的相位差，外推时相位可能转到训练从未见过的区域，点积统计会漂。ALiBi 的位置通道极度贫乏：只有距离的一次函数。贫乏反而是外推的条件——没有高频相位可以溢出，没有嵌入行可以缺失。</p><p>代价同样清楚。不能表达「恰好间隔 3」与「恰好间隔 11」的非单调模式，除非内容通道自己学出来。ALiBi 赌的是：对语言建模，单调的近邻优先已经覆盖了位置编码该做的大部分工作，剩下的交给内容注意力。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>ALiBi 的外推不是无限的。训练窗口若极短，内容注意力本身可能没学过「隔很远仍要对齐」的任务，偏置只能保证远处不会被随机放大，不能凭空制造长程算法。评测时常见的是困惑度随长度缓升，而不是硬截断；但若下游是需要精确相对偏移的复制或括号匹配，线性势可能不够。</p><p>与后来的长上下文路线相比，ALiBi 改的是架构，不是把 RoPE 模型在推理时拉长。已用 RoPE 训好的权重不能「换成 ALiBi」而不重训。它也没有 YaRN 那种按频率分段的旋转变换，因此不解决 RoPE 基数与插值问题——那是另一篇文章的对象。</p><p><span class="marginnote">工程上 ALiBi 几乎零参数：没有位置表，斜率按头数写死。内核里要能给注意力分数加沿对角线的线性偏置；不少 fused attention 需要专门支持，否则会退回物化整块分数矩阵，吞吐变差。</span></p><h3 id="适用场景与不该期待的东西" tabindex="-1">适用场景与不该期待的东西 <a class="header-anchor" href="#适用场景与不该期待的东西" aria-label="Permalink to &quot;适用场景与不该期待的东西&quot;">​</a></h3><p>适合从零训练、目标是「上下文可以比训练更长」的解码器。不太适合必须保留已有 RoPE 权重、只想把窗口从 4k 拉到 32k 的续训场景。也不该把它理解成注意力复杂度从二次变成线性——偏置不改变 \\(QK^\\top\\) 的形状，只改变 softmax 的形状。长度仍受二次注意力与 KV 缓存限制；ALiBi 解决的是位置外推，不是计算外推。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ALiBi 把位置写成注意力 logits 上与距离成正比的负偏置，而不是写成可加或可旋转的位置向量。</li><li>斜率按头固定为几何序列，使不同头拥有不同的有效感受野。</li><li>训练长度可以短于推理长度，因为相对距离在短窗口里已经密集出现。</li><li>位置通道很贫乏：擅长近邻优先，不擅长复杂的非单调相对模式。</li><li>不能把现成 RoPE 模型无损换成 ALiBi；二者改变的是不同的位置接口。</li><li>它不降低注意力的二次代价，只改善长度外推时的位置归纳偏置。</li><li>出处：Press、Smith、Lewis，<em>Train Short, Test Long: Attention with Linear Biases Enables Input Length Extrapolation</em>，2021。</li></ul>',19))])}const P=r(E,[["render",m]]);export{L as __pageData,P as default};
